import type { FlagConfig, FlagDefinition } from 'tinyflag';

/** Generate TypeScript type definitions from a FlagConfig. */
export function generateTypes(config: FlagConfig): string {
  const lines: string[] = [
    '// Auto-generated by tinyflag — do not edit',
    '',
    'export interface TinyFlagDefinitions {',
  ];

  const flagNames = Object.keys(config.flags).sort();

  for (const name of flagNames) {
    const flag = config.flags[name];
    let variantType = 'never';

    if (flag.variants && flag.variants.length > 0) {
      variantType = flag.variants.map((v) => `'${v.name}'`).join(' | ');
    }

    const configType = flag.config ? `${toPascalCase(name)}Config` : 'never';
    lines.push(`  '${name}': { variants: ${variantType}; config: ${configType} };`);
  }

  lines.push('}');
  lines.push('');

  // Flag name union type
  lines.push(`export type FlagName = ${flagNames.length > 0 ? flagNames.map((n) => `'${n}'`).join(' | ') : 'never'};`);
  lines.push('');

  // Generate config interfaces
  for (const name of flagNames) {
    const flag = config.flags[name];
    if (!flag.config) continue;

    const ifaceName = `${toPascalCase(name)}Config`;
    lines.push(`export interface ${ifaceName} {`);
    for (const [key, value] of Object.entries(flag.config)) {
      const tsType = inferTsType(value);
      lines.push(`  ${key}: ${tsType};`);
    }
    lines.push('}');
    lines.push('');
  }

  return lines.join('\n');
}

/** Generate an OpenAPI 3.1 specification from flag definitions. */
export function generateOpenAPISpec(config: FlagConfig): object {
  const flagNames = Object.keys(config.flags).sort();
  const properties: Record<string, object> = {};
  const variantEnums: Record<string, object> = {};

  for (const name of flagNames) {
    const flag = config.flags[name];
    const flagSchema: Record<string, unknown> = {
      type: 'object',
      description: flag.description || `Feature flag: ${name}`,
      properties: {
        enabled: { type: 'boolean' },
        variant: flag.variants && flag.variants.length > 0
          ? { type: 'string', enum: flag.variants.map((v) => v.name) }
          : { type: 'string', nullable: true },
      },
      required: ['enabled'],
    };
    properties[name] = flagSchema;

    if (flag.variants && flag.variants.length > 0) {
      variantEnums[`${toPascalCase(name)}Variant`] = {
        type: 'string',
        enum: flag.variants.map((v) => v.name),
      };
    }
  }

  return {
    openapi: '3.1.0',
    info: {
      title: 'TinyFlag Feature Flags',
      version: '1.0.0',
      description: 'Auto-generated from flag definitions by tinyflag codegen',
    },
    paths: {
      '/flags': {
        get: {
          operationId: 'getFlags',
          summary: 'Get all flag evaluations',
          parameters: [
            { name: 'x-user-id', in: 'header', schema: { type: 'string' }, description: 'User ID for rollout bucketing' },
          ],
          responses: {
            '200': {
              description: 'Flag evaluation results',
              content: {
                'application/json': {
                  schema: {
                    type: 'object',
                    properties: {
                      version: { type: 'integer' },
                      flags: {
                        type: 'object',
                        properties,
                      },
                    },
                  },
                },
              },
            },
          },
        },
      },
      '/flags/{flagName}': {
        get: {
          operationId: 'getFlag',
          summary: 'Get a single flag evaluation',
          parameters: [
            { name: 'flagName', in: 'path', required: true, schema: { type: 'string', enum: flagNames } },
            { name: 'x-user-id', in: 'header', schema: { type: 'string' } },
          ],
          responses: {
            '200': {
              description: 'Single flag evaluation',
              content: {
                'application/json': {
                  schema: {
                    type: 'object',
                    properties: {
                      enabled: { type: 'boolean' },
                      variant: { type: 'string', nullable: true },
                    },
                  },
                },
              },
            },
            '404': { description: 'Flag not found' },
          },
        },
      },
    },
    components: {
      schemas: {
        ...variantEnums,
        FlagName: {
          type: 'string',
          enum: flagNames,
        },
      },
    },
  };
}

/** Generate a GraphQL schema from flag definitions. */
export function generateGraphQLSchema(config: FlagConfig): string {
  const flagNames = Object.keys(config.flags).sort();
  const lines: string[] = [
    '# Auto-generated by tinyflag — do not edit',
    '',
  ];

  // Generate variant enums
  for (const name of flagNames) {
    const flag = config.flags[name];
    if (flag.variants && flag.variants.length > 0) {
      const enumName = `${toPascalCase(name)}Variant`;
      lines.push(`enum ${enumName} {`);
      for (const v of flag.variants) {
        lines.push(`  ${v.name.replace(/-/g, '_').toUpperCase()}`);
      }
      lines.push('}');
      lines.push('');
    }
  }

  // FlagName enum
  lines.push('enum FlagName {');
  for (const name of flagNames) {
    lines.push(`  ${name.replace(/-/g, '_').toUpperCase()}`);
  }
  lines.push('}');
  lines.push('');

  // Flag result types per flag with variants
  for (const name of flagNames) {
    const flag = config.flags[name];
    const typeName = `${toPascalCase(name)}Flag`;
    const variantType = flag.variants && flag.variants.length > 0
      ? `${toPascalCase(name)}Variant`
      : 'String';

    lines.push(`type ${typeName} {`);
    lines.push('  enabled: Boolean!');
    lines.push(`  variant: ${variantType}`);
    if (flag.config) {
      lines.push(`  config: ${toPascalCase(name)}Config`);
    }
    lines.push('}');
    lines.push('');

    // Config type if present
    if (flag.config) {
      lines.push(`type ${toPascalCase(name)}Config {`);
      for (const [key, value] of Object.entries(flag.config)) {
        lines.push(`  ${key}: ${inferGraphQLType(value)}`);
      }
      lines.push('}');
      lines.push('');
    }
  }

  // Root Flags type
  lines.push('type Flags {');
  for (const name of flagNames) {
    const typeName = `${toPascalCase(name)}Flag`;
    const fieldName = name.replace(/-/g, '_');
    lines.push(`  ${fieldName}: ${typeName}!`);
  }
  lines.push('}');
  lines.push('');

  // Query root
  lines.push('type Query {');
  lines.push('  flags(userId: String): Flags!');
  lines.push('  flag(name: FlagName!, userId: String): Boolean!');
  lines.push('}');
  lines.push('');

  return lines.join('\n');
}

/** Check if generated output matches the current flag definitions. Returns null if up-to-date, or diff info. */
export function checkGeneratedTypes(config: FlagConfig, existingContent: string): { stale: boolean; expected: string } {
  const expected = generateTypes(config);
  return { stale: expected.trim() !== existingContent.trim(), expected };
}

function toPascalCase(name: string): string {
  return name
    .split('-')
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('');
}

function inferTsType(value: unknown): string {
  if (value === null || value === undefined) return 'unknown';
  if (typeof value === 'string') return 'string';
  if (typeof value === 'number') return 'number';
  if (typeof value === 'boolean') return 'boolean';
  if (Array.isArray(value)) return 'unknown[]';
  return 'Record<string, unknown>';
}

function inferGraphQLType(value: unknown): string {
  if (value === null || value === undefined) return 'String';
  if (typeof value === 'string') return 'String';
  if (typeof value === 'number') return Number.isInteger(value) ? 'Int' : 'Float';
  if (typeof value === 'boolean') return 'Boolean';
  return 'String';
}
